for asset in ('css/site.css', 'js/site.js', 'fonts/atkinson-400.woff2', 'fonts/atkinson-700.woff2', 'fonts/bricolage-700.woff2', 'docs/catalog.pdf', 'img/don-dye-logo.png', 'img/hero-transparent.png', 'img/single-transparent.png', 'img/drive-transparent.png'):
 dest = SITE/'assets'/asset
 dest.parent.mkdir(parents=True, exist_ok=True)
 shutil.copyfile(ROOT/'src/assets'/asset, dest)
imgs={'hero':'dbl_row_ball_bearing_idler_.png','single':'v-belt_idler_pulleys.png','drive':'vbelt_drive_pulley_img1.png','v-single':'srb_diagram.png','flat-single':'srb_diagram2.png','v-double':'v-idler_drb_img1.png','flat-faced':'flatfaced_idler_drb_img1.png','flat-flanged':'flatflanged_idler_drb_img1.png','a':'a-grove_drive_pulley.png','b':'b-grove_drive_pulley.png','c':'c-grove_drive_pulley.png','special':'special-grove_drive_pulley.png'}
for name,source in imgs.items():
 if name not in ('hero', 'single', 'drive'):
  # Line drawings: color-to-alpha against white so fine dimension lines survive on any page color.
  import numpy as np
  a=np.asarray(Image.open(ROOT/'src/assets/img/images'/source).convert('RGBA')).astype(float)
  d=255-a[...,:3]; d=np.where(d<=6,0,(d-6)*255/249); al=d.max(2)/255
  col=np.clip(np.where(al[...,None]>0,255-d/np.maximum(al,1e-6)[...,None],0),0,255)
  Image.fromarray(np.dstack([col,al*a[...,3]]).round().astype('uint8'),'RGBA').save(SITE/'assets/img'/f'{name}-transparent.png',optimize=True)
def image(name,alt, eager=False):
 filename=f'{name}-transparent.png'
 im=Image.open(SITE/'assets/img'/filename); w,h=im.size
 webp=f'{name}-transparent.webp'
 im.save(SITE/'assets/img'/webp, 'WEBP', lossless=True, method=6)
 return f'<img src="/assets/img/{webp}" alt="{escape(alt)}" width="{w}" height="{h}" decoding="async" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'
def table(key, label=None):
 rows=TABLES[key]
 def clean(s): return escape(' '.join(s.split()))
 head=''.join('<th scope="col">'+clean(x or 'Part No.')+'</th>' for x in rows[0])
 body=''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+clean(c)+('</th>' if i==0 else '</td>') for i,c in enumerate(row))+'</tr>' for row in rows[1:])
 return f'<div class="table-scroller"><div class="scroll-cue" aria-hidden="true">Scroll for more columns →</div><div class="table-wrap" tabindex="0" role="region" aria-label="{escape(label or key.replace('_', ' ') + ' dimensions')}"><table><caption class="visually-hidden">{escape(label or key.replace("_", " ") + " dimensions")}</caption><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div></div>'
def section(id,title,key,img):
 return f'<section class="product-section" id="{id}"><div class="section-heading"><h2>{title}</h2></div><div class="product-layout"><figure class="diagram"><a href="/assets/img/{img}-transparent.png">{image(img,title+" diagram")}</a></figure>{table(key,title + " dimensions")}</div></section>'
