 subnav={'/idler-pulleys/single-row/':[('v-idler','V-Idler'),('flat-idler','Flat Idler')],'/idler-pulleys/double-row/':[('v-idler','V-Idler'),('flat-faced','Flat Faced'),('flat-flanged','Flat Flanged')],'/drive-pulleys/':[('a-groove','A Groove'),('b-groove','B Groove'),('c-groove','C Groove'),('special-groove','Special Groove')]}
